#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAXLEN 64
#define DP_SIZE ((MAXLEN + 1) * (MAXLEN + 1))

static int main_dp[DP_SIZE];

static inline int *dp_cell(int i, int j) {
    return &main_dp[i * (MAXLEN + 1) + j];
}

int main(int argc, char *argv[]) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    const char *s1 = argv[1];
    const char *s2 = argv[2];
    size_t len1 = strlen(s1);
    size_t len2 = strlen(s2);
    if (len1 > MAXLEN || len2 > MAXLEN) {
        puts("TOO_LONG");
        return 0;
    }
    for (size_t i = 0; i <= len1; ++i) *dp_cell(i, 0) = (int)i;
    for (size_t j = 0; j <= len2; ++j) *dp_cell(0, j) = (int)j;
    for (size_t i = 1; i <= len1; ++i) {
        for (size_t j = 1; j <= len2; ++j) {
            int cost = (s1[i - 1] == s2[j - 1]) ? 0 : 1;
            int del = *dp_cell(i - 1, j) + 1;
            int ins = *dp_cell(i, j - 1) + 1;
            int sub = *dp_cell(i - 1, j - 1) + cost;
            int best = del;
            if (ins < best) best = ins;
            if (sub < best) best = sub;
            *dp_cell(i, j) = best;
        }
    }
    printf("%d\n", *dp_cell(len1, len2));
    return 0;
}
